    // A periodic signal: the same job, on schedule.
    return 0.17 * sin(9.0 * p.x - uTime * 1.2) * (0.75 + 0.25 * cos(2.4 * p.y)) + 0.05 * sin(5.0 * p.y + uTime * 0.6);
